Definition rs_ms (pc : Z) (rax : word) (sp : word) (gp tp t0 t1 t2 : word) (s0x : word) (E : Z) (a0 a1 a2 a3 a4 a5 a6 a7 : word)
    (tot fb : Z) (s4x s6x s9x : word) (t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -208)) gp tp t0 t1 t2 s0x (wz E) a0 a1 a2 a3 a4 a5 a6 a7
          (wz tot) (wz (Z.shiftr (fb + 16) 3 + 2147450880)) s4x (wz fb) s6x (wz (fb + 16)) (wz (fb + 8)) s9x
          (wz 2147450880) (wz (Z.shiftr (fb + 8) 3 + 2147450880)) t3 t4 t5 t6)
     F (Z_to_bv 64 pc) fc None m (seg_rom asegs).

Definition rs_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

