(* [comment removed for export] *)
Definition rs_frame (m : mem) (sp : word) (E bs P : Z) (mw1 mw2 : cell) (t2c optc : list cell) : Prop :=
  rw_cells asegs m (bv_unsigned sp + -208) [C8 (wz (E + 16)); C8 (wz ASYSCAT); C8 (wz bs); C8 (wz P)]
  /\ rw_cells asegs m (bv_unsigned sp + -176) [mw1; mw2] /\ csize mw1 = 8%nat /\ csize mw2 = 8%nat
  /\ rw_cells asegs m (bv_unsigned sp + -160) [C8 (wz (Z.shiftr E 3))]
  /\ rw_cells asegs m (bv_unsigned sp + -152) t2c /\ cells_size t2c = 24%nat
  /\ rw_cells asegs m (bv_unsigned sp + -128) optc /\ cells_size optc = 24%nat.

