(* [comment removed for export] *)
Definition rs_entry_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo E bs fb P : Z) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' (jm1 jm2 jt2 jopt : list byte) (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
           munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ stk asegs m' lo (bv_unsigned sp + -208)
        /\ rs_frame m' sp E bs P (CB 8 jm1) (CB 8 jm2) [CB 24 jt2] [CB 24 jopt]
        /\ rw_cells asegs m' (bv_unsigned sp + -104) (rs_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
        /\ rw_cells asegs m' fb (FlatBufCells FB)
        /\ rw_cells asegs m' E (ErrCodeCells EC_clear)
        /\ ACONST m'
        /\ (   (fb_size FB = 0 /\ ms' = rs_ms RS_DOREAD rax sp gp tp t0 t1 t2 s0 E a0 a1 a2 a3 a4 a5 a6 a7 0 fb (wz (E + 8)) (wz (E + 16)) s9 t3 t4 t5 t6 F fc m')
            \/ (0 < fb_size FB /\ ms' = rs_ms RS_PARSE rax sp gp tp t0 t1 t2 s0 E a0 a1 a2 a3 a4 a5 a6 a7 0 fb (wz (E + 8)) (wz (E + 16)) s9 t3 t4 t5 t6 F fc m')).
