Lemma rs_entry : forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo shi E bs fb P : Z) (FB : fbv) (ej : list byte),
  rw_cells asegs m fb (FlatBufCells FB) -> fb mod 8 = 0 -> bv_unsigned sp <= fb -> fb + 48 <= shi ->
  rw_cells asegs m E [CB 24 ej] -> aapp E 24 -> accessible m E 24 -> shvis m E (E + 24) -> E mod 8 = 0 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= bs < 2^64 -> 0 <= P < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + 208 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m -> stack0 m lo shi ->
  evt asegs (rs_entry_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo E bs fb P FB m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz bs) (wz fb) (wz P) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_HTTP_READ_SOME) fc None m (seg_rom asegs)).
