(* [comment removed for export] *)
Lemma rs_parse : forall rax sp gp tp t0 t1 t2 s0x a0 a1 a2 a3 a4 a5 a6 a7 s4x s6x s9x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo shi E bs fb P tot : Z) (FB : fbv) (mw1 mw2 : cell) (t2c optc : list cell),
  rs_frame m sp E bs P mw1 mw2 t2c optc ->
  rw_cells asegs m fb (FlatBufCells FB) -> fb mod 8 = 0 -> bv_unsigned sp <= fb -> fb + 48 <= shi ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= P < 2^64 -> 0 <= tot < 2^64 ->
  lo + 208 <= bv_unsigned sp -> aceil <= lo -> stack0 m lo shi -> mem_inv asegs m ->
  evt asegs (fun ms' => ms' = rs_ms P_A_BP_PUT (Z_to_bv 64 RS_PUTRET) sp gp tp t0 t1 t2 s0x E (wz P) (wz (fb_in FB)) (wz (fb_size FB)) (wz E) a4 a5 a6 a7
                                  tot fb s4x s6x s9x t3 t4 t5 t6 F fc m
                       /\ munch [] m m /\ wmono asegs m m /\ mem_inv asegs m)
